INO_st.name='INO';
INO_st.lat=44.35;
INO_st.lon=26.03;
INO_st.alt=93;
INO_st.env='con';
INO_st.footp='U';
%%

INO_rd= read_all_data_PSI_Ttable('AE33','lev2','C:/github_trend/raw_data/INO_AE33/');%read all nasa ames read_betsy_2026('INO_tsi_psap_clap_eco',INO_st.name);
names_rd=fieldnames(INO_rd);

% REST NOT RIGHT
%%
datevec(INO_rd.Time(1)) %data since 2016 %[output:87b350db]
datevec(INO_rd.Time(end)) % 2025 %[output:47a229f5]
% % prctile(INO_rd.U0_S11,[5 50 95]) % < 38% ok no need to compute dry trend
% % prctile(INO_rd.U1_S11,[5 50 95])
figure; %[output:86c2da4a] %[output:1a26b2e4] %[output:1e186828] %[output:526aac07] %[output:21b69842]
plot(INO_rd.Time, INO_rd{:,2:8},'.');
ylabel('Abs. Coef.');
title('INO');
grid on;
